  // Pre-render icons
  const iconChip = await iconToBase64Png(FaMicrochip, "#06B6D4", 256);
  const iconMemory = await iconToBase64Png(FaMemory, "#06B6D4", 256);
  const iconBolt = await iconToBase64Png(FaBolt, "#F59E0B", 256);
  const iconExpand = await iconToBase64Png(FaExpandArrowsAlt, "#10B981", 256);
  const iconCompress = await iconToBase64Png(FaCompressArrowsAlt, "#06B6D4", 256);
  const iconRocket = await iconToBase64Png(FaRocket, "#10B981", 256);
  const iconCheck = await iconToBase64Png(FaCheckCircle, "#10B981", 256);
  const iconBrain = await iconToBase64Png(FaBrain, "#06B6D4", 256);
  const iconImage = await iconToBase64Png(FaImage, "#F59E0B", 256);
  const iconMobile = await iconToBase64Png(FaMobileAlt, "#06B6D4", 256);
  const iconChart = await iconToBase64Png(FaChartBar, "#10B981", 256);
  const iconLayer = await iconToBase64Png(FaLayerGroup, "#06B6D4", 256);
  const iconEye = await iconToBase64Png(FaEye, "#10B981", 256);
  const iconCogs = await iconToBase64Png(FaCogs, "#64748B", 256);
  const iconArrow = await iconToBase64Png(FaArrowRight, "#06B6D4", 256);

  // Load figure images
  const fig3 = fs.readFileSync("/app/benchmark/assets/figure_3.jpg").toString("base64");
  const fig6 = fs.readFileSync("/app/benchmark/assets/figure_6.jpg").toString("base64");
  const fig2 = fs.readFileSync("/app/benchmark/assets/figure_2.jpg").toString("base64");
  const imgFig3 = "image/jpeg;base64," + fig3;
  const imgFig6 = "image/jpeg;base64," + fig6;
  const imgFig2 = "image/jpeg;base64," + fig2;

  // ==================== SLIDE 1: Title ====================
  let s1 = pres.addSlide();
  s1.background = { color: C.darkBg };

  // Decorative shapes
  s1.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 5.625, fill: { color: C.darkBg2, transparency: 60 } });
  // Teal accent bar at top
  s1.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal } });
  // Bottom accent
  s1.addShape(pres.shapes.RECTANGLE, { x: 3.5, y: 4.4, w: 3, h: 0.04, fill: { color: C.teal } });

  // Title
  s1.addText("SmolVLM", {
    x: 0.8, y: 1.0, w: 8.4, h: 1.1,
    fontSize: 52, fontFace: FONT_H, color: C.white, bold: true, margin: 0
  });
  s1.addText("Redefining Small and Efficient Multimodal Models", {
    x: 0.8, y: 2.0, w: 8.4, h: 0.7,
    fontSize: 24, fontFace: FONT_H, color: C.teal, margin: 0
  });
  // Authors
  s1.addText("Hugging Face  &  Stanford University", {
    x: 0.8, y: 3.0, w: 8.4, h: 0.5,
    fontSize: 16, fontFace: FONT_B, color: C.slate300, margin: 0
  });
  // Tagline
  s1.addText("Sub-1GB inference  |  Competitive with 300× larger models  |  Fully open-source", {
    x: 0.8, y: 3.6, w: 8.4, h: 0.5,
    fontSize: 13, fontFace: FONT_B, color: C.slate300, margin: 0
  });
  // ArXiv reference
  s1.addText("arXiv: 2504.05299", {
    x: 0.8, y: 4.6, w: 8.4, h: 0.4,
    fontSize: 11, fontFace: FONT_B, color: C.textMuted, margin: 0
  });

  // ==================== SLIDE 2: Problem/Motivation ====================
  let s2 = pres.addSlide();
  s2.background = { color: C.lightBg };

  // Title bar
  s2.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.9, fill: { color: C.darkBg } });
  s2.addText("Large VLMs Are Powerful but Impractical for Edge Deployment", {
    x: 0.6, y: 0.1, w: 8.8, h: 0.7, fontSize: 22, fontFace: FONT_H, color: C.white, bold: true, margin: 0
  });

  // Left column: Problem statement
  s2.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 1.2, w: 4.3, h: 3.9, fill: { color: C.white }, shadow: cardShadow() });
  // Accent bar on left card
  s2.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 1.2, w: 0.06, h: 3.9, fill: { color: C.red } });

  s2.addImage({ data: iconMemory, x: 0.8, y: 1.4, w: 0.4, h: 0.4 });
  s2.addText("The Edge Deployment Gap", {
    x: 1.3, y: 1.4, w: 3.2, h: 0.4, fontSize: 16, fontFace: FONT_H, color: C.textDark, bold: true, margin: 0
  });

  s2.addText([
    { text: "State-of-the-art VLMs demand massive resources:", options: { breakLine: true, fontSize: 12, color: C.textMid } },
    { text: "", options: { breakLine: true, fontSize: 8 } },
    { text: "Molmo-A1B-7B: 27.7 GB RAM", options: { bullet: true, breakLine: true, fontSize: 12, color: C.textDark, bold: true } },
    { text: "InternVL2-2B: ~8 GB RAM", options: { bullet: true, breakLine: true, fontSize: 12, color: C.textDark, bold: true } },
    { text: "Typical mobile device: 4–8 GB total", options: { bullet: true, breakLine: true, fontSize: 12, color: C.red, bold: true } },
    { text: "", options: { breakLine: true, fontSize: 8 } },
    { text: "Edge and mobile devices cannot host these models, blocking on-device multimodal AI.", options: { fontSize: 12, color: C.textMuted, italic: true } }
  ], { x: 0.8, y: 2.0, w: 3.8, h: 2.8, valign: "top", margin: 0 });

  // Right column: Stat callouts
  // Stat 1
  s2.addShape(pres.shapes.RECTANGLE, { x: 5.2, y: 1.2, w: 4.3, h: 1.15, fill: { color: C.white }, shadow: cardShadow() });
  s2.addText("27.7 GB", { x: 5.4, y: 1.25, w: 2.0, h: 0.6, fontSize: 32, fontFace: FONT_H, color: C.red, bold: true, margin: 0 });
  s2.addText("GPU RAM for Molmo-A1B-7B", { x: 5.4, y: 1.9, w: 3.8, h: 0.35, fontSize: 11, fontFace: FONT_B, color: C.textMuted, margin: 0 });

  // Stat 2
  s2.addShape(pres.shapes.RECTANGLE, { x: 5.2, y: 2.55, w: 4.3, h: 1.15, fill: { color: C.white }, shadow: cardShadow() });
  s2.addText("7B+", { x: 5.4, y: 2.6, w: 2.0, h: 0.6, fontSize: 32, fontFace: FONT_H, color: C.amber, bold: true, margin: 0 });
  s2.addText("Parameters in smallest efficient OS model", { x: 5.4, y: 3.25, w: 3.8, h: 0.35, fontSize: 11, fontFace: FONT_B, color: C.textMuted, margin: 0 });

  // Stat 3
  s2.addShape(pres.shapes.RECTANGLE, { x: 5.2, y: 3.9, w: 4.3, h: 1.15, fill: { color: C.white }, shadow: cardShadow() });
  s2.addText("< 1 GB", { x: 5.4, y: 3.95, w: 2.0, h: 0.6, fontSize: 32, fontFace: FONT_H, color: C.emerald, bold: true, margin: 0 });
  s2.addText("SmolVLM-256M RAM usage (batch=1)", { x: 5.4, y: 4.6, w: 3.8, h: 0.35, fontSize: 11, fontFace: FONT_B, color: C.textMuted, margin: 0 });

  // ==================== SLIDE 3: Architecture Overview ====================
  let s3 = pres.addSlide();
  s3.background = { color: C.lightBg };

  s3.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.9, fill: { color: C.darkBg } });
  s3.addText("SmolVLM Architecture: Image Splitting, Pixel Shuffle, and SmolLM2", {
    x: 0.6, y: 0.1, w: 8.8, h: 0.7, fontSize: 20, fontFace: FONT_H, color: C.white, bold: true, margin: 0
  });

  // Architecture flow diagram using shapes
  const flowY = 1.3;
  const boxH = 0.8;
  const boxW = 1.4;
  const gap = 0.15;

  // Pipeline boxes
  const steps = [
    { label: "Image\nSplitting", color: C.teal, x: 0.4 },
    { label: "SigLIP\nEncoder", color: C.tealDark, x: 2.1 },
    { label: "Pixel\nShuffle", color: C.emerald, x: 3.8 },
    { label: "Linear\nProjection", color: C.amber, x: 5.5 },
    { label: "SmolLM2\nBackbone", color: C.darkBg2, x: 7.2 },
  ];

  for (const step of steps) {
    s3.addShape(pres.shapes.RECTANGLE, {
      x: step.x, y: flowY, w: boxW, h: boxH,
      fill: { color: step.color }, shadow: cardShadow()
    });
    s3.addText(step.label, {
      x: step.x, y: flowY, w: boxW, h: boxH,
      fontSize: 11, fontFace: FONT_H, color: C.white, bold: true, align: "center", valign: "middle", margin: 0
    });
  }

  // Arrows between boxes
  const arrowY = flowY + boxH / 2 - 0.1;
  for (let i = 0; i < steps.length - 1; i++) {
    const ax = steps[i].x + boxW + 0.02;
    s3.addShape(pres.shapes.LINE, {
      x: ax, y: arrowY, w: gap - 0.04, h: 0,
      line: { color: C.textMuted, width: 2 }
    });
  }

  // Figure image
  const fig3W = 9.0;
  const fig3H = 2.3;
  const fig3X = (10 - fig3W) / 2;
  s3.addImage({ data: imgFig3, x: fig3X, y: 2.4, w: fig3W, h: fig3H, sizing: { type: "contain", w: fig3W, h: fig3H } });

  // Key steps below
  s3.addShape(pres.shapes.RECTANGLE, { x: 0.4, y: 4.85, w: 9.2, h: 0.55, fill: { color: C.white }, shadow: cardShadow() });
  s3.addText([
    { text: "1. ", options: { bold: true, color: C.teal } },
    { text: "Images split into sub-images   ", options: { color: C.textDark, fontSize: 10 } },
    { text: "2. ", options: { bold: true, color: C.tealDark } },
    { text: "SigLIP encodes visual features   ", options: { color: C.textDark, fontSize: 10 } },
    { text: "3. ", options: { bold: true, color: C.emerald } },
    { text: "Pixel shuffle compresses tokens   ", options: { color: C.textDark, fontSize: 10 } },
    { text: "4. ", options: { bold: true, color: C.amber } },
    { text: "Linear projection aligns to LM space   ", options: { color: C.textDark, fontSize: 10 } },
    { text: "5. ", options: { bold: true, color: C.darkBg2 } },
    { text: "SmolLM2 generates text output", options: { color: C.textDark, fontSize: 10 } },
  ], { x: 0.55, y: 4.88, w: 9.0, h: 0.5, fontFace: FONT_B, valign: "middle", margin: 0 });

  // ==================== SLIDE 4: Compute Allocation ====================
  let s4 = pres.addSlide();
  s4.background = { color: C.lightBg };

  s4.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.9, fill: { color: C.darkBg } });
  s4.addText("Smaller Vision Encoders Outperform Larger Ones in Compact VLMs", {
    x: 0.6, y: 0.1, w: 8.8, h: 0.7, fontSize: 20, fontFace: FONT_H, color: C.white, bold: true, margin: 0
  });

  // Finding label
  s4.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 1.1, w: 1.6, h: 0.35, fill: { color: C.teal } });
  s4.addText("Finding 1", { x: 0.5, y: 1.1, w: 1.6, h: 0.35, fontSize: 12, fontFace: FONT_H, color: C.white, bold: true, align: "center", valign: "middle", margin: 0 });

  // Bar chart: Encoder comparison
