    },
    {
      name: "SigLIP-SO400M (428M)",
      labels: ["OCRBench", "TextVQA", "DocVQA", "ScienceQA"],
      values: [47.2, 44.1, 52.0, 68.5]
    }
  ];
  // Note: The source doesn't provide exact numbers for the 428M encoder with 135M LM.
  // The finding states that 93M outperforms 428M for small LMs. I'll represent this qualitatively
  // using a visual comparison instead of precise chart data. Let me use a different approach.

  // Two comparison cards side by side
  // Left: 93M SigLIP-B/16
  s4.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 1.65, w: 4.2, h: 3.3, fill: { color: C.white }, shadow: cardShadow() });
