  // Performance bars for 93M encoder
  const barData93 = [
    { label: "OCRBench", val: 52.6, max: 80, color: C.emerald },
    { label: "TextVQA", val: 50.2, max: 80, color: C.emerald },
    { label: "DocVQA", val: 58.3, max: 80, color: C.emerald },
    { label: "ScienceQA", val: 73.8, max: 80, color: C.emerald },
