  let barY = 2.65;
  for (const b of barData93) {
    const barW = (b.val / b.max) * 3.2;
    s4.addText(b.label, { x: 0.8, y: barY, w: 1.1, h: 0.3, fontSize: 10, fontFace: FONT_B, color: C.textMid, margin: 0 });
