    { text: "", options: { breakLine: true, fontSize: 8 } },
    { text: "Edge and mobile devices cannot host these models, blocking on-device multimodal AI.", options: { fontSize: 12, color: C.textMuted, italic: true } }
  ], { x: 0.8, y: 2.0, w: 3.8, h: 2.8, valign: "top", margin: 0 });

  // Right column: Stat callouts
  // Stat 1
  s2.addShape(pres.shapes.RECTANGLE, { x: 5.2, y: 1.2, w: 4.3, h: 1.15, fill: { color: C.white }, shadow: cardShadow() });
  s2.addText("27.7 GB", { x: 5.4, y: 1.25, w: 2.0, h: 0.6, fontSize: 32, fontFace: FONT_H, color: C.red, bold: true, margin: 0 });
  s2.addText("GPU RAM for Molmo-A1B-7B", { x: 5.4, y: 1.9, w: 3.8, h: 0.35, fontSize: 11, fontFace: FONT_B, color: C.textMuted, margin: 0 });

  // Stat 2
  s2.addShape(pres.shapes.RECTANGLE, { x: 5.2, y: 2.55, w: 4.3, h: 1.15, fill: { color: C.white }, shadow: cardShadow() });
  s2.addText("7B+", { x: 5.4, y: 2.6, w: 2.0, h: 0.6, fontSize: 32, fontFace: FONT_H, color: C.amber, bold: true, margin: 0 });
  s2.addText("Parameters in smallest efficient OS model", { x: 5.4, y: 3.25, w: 3.8, h: 0.35, fontSize: 11, fontFace: FONT_B, color: C.textMuted, margin: 0 });

  // Stat 3
  s2.addShape(pres.shapes.RECTANGLE, { x: 5.2, y: 3.9, w: 4.3, h: 1.15, fill: { color: C.white }, shadow: cardShadow() });
  s2.addText("< 1 GB", { x: 5.4, y: 3.95, w: 2.0, h: 0.6, fontSize: 32, fontFace: FONT_H, color: C.emerald, bold: true, margin: 0 });
  s2.addText("SmolVLM-256M RAM usage (batch=1)", { x: 5.4, y: 4.6, w: 3.8, h: 0.35, fontSize: 11, fontFace: FONT_B, color: C.textMuted, margin: 0 });

  // ==================== SLIDE 3: Architecture Overview ====================
