arguments.old_string:
// Architecture flow diagram using shapes
const flowY = 1.2;
const boxH = 0.75;
const boxW = 1.35;

// Pipeline boxes (evenly spaced with wider arrows)
const steps = [
  { label: "Image\nSplitting", color: C.teal, x: 0.6 },
  { label: "SigLIP\nEncoder", color: C.tealDark, x: 2.35 },
  { label: "Pixel\nShuffle", color: C.emerald, x: 4.1 },
  { label: "Linear\nProjection", color: C.amber, x: 5.85 },
  { label: "SmolLM2\nBackbone", color: C.darkBg2, x: 7.6 },
];

for (const step of steps) {
  s3.addShape(pres.shapes.RECTANGLE, {
    x: step.x, y: flowY, w: boxW, h: boxH,
    fill: { color: step.color }, shadow: cardShadow()
  });
  s3.addText(step.label, {
    x: step.x, y: flowY, w: boxW, h: boxH,
    fontSize: 11, fontFace: FONT_H, color: C.white, bold: true, align: "center", valign: "middle", margin: 0
  });
}

// Arrows between boxes (wider, more visible)
const arrowY = flowY + boxH / 2 - 0.05;
for (let i = 0; i < steps.length - 1; i++) {
  const ax = steps[i].x + boxW + 0.08;
  const aw = steps[i + 1].x - (steps[i].x + boxW) - 0.16;
  s3.addShape(pres.shapes.LINE, {
    x: ax, y: arrowY, w: aw, h: 0,
    line: { color: C.teal, width: 2.5, dashType: "dash" }
  });
}

